package com.sirithree.shopops.admin.benchmark.v1.dataset.stage7a;
import static org.assertj.core.api.Assertions.assertThat; import org.junit.jupiter.api.Test; import java.util.Map;
class TaskScaleupManifestTest { @Test void candidateManifestSeparatesScaleupFromFormalExecution() throws Exception { Map<String,Object>d=Stage7ATaskDatasetSupport.objectResource("/benchmark/v1/benchmark-task-stage7a-scaleup-candidate-manifest.json"); assertThat(d.get("status")).isEqualTo("EXPANSION_CANDIDATE"); assertThat(d.get("caseCount")).isEqualTo(189); assertThat(d.get("semanticRootCount")).isEqualTo(116); assertThat(d.get("trueTestExclusiveRootCount")).isEqualTo(63); assertThat(d.get("formalRunOccurred")).isEqualTo(false); assertThat(d.get("heldOutExecutionOccurred")).isEqualTo(false); }}
